RE_REPO = re.compile(r"^[\w.-]+/[\w.-]+$")
LY_DO_WD = "graphql_bi_chan_trong_phien_claude; cho P-B"
KET_BUOC = ("success", "failure", "cancelled", "skipped", "neutral")
LOI_JOB = ("failure", "cancelled", "timed_out", "action_required", "startup_failure", "stale")
